        return safe.astype(str).to_numpy(dtype=object, copy=False)

    @staticmethod
    def _lcp(left: str, right: str) -> int:
        """Compute character LCP using binary searched C-level string slice equality."""
        limit = min(len(left), len(right))
        if limit == 0:
            return 0
        if left == right:
            return limit

        low, high = 0, limit
        while low < high:
            middle = (low + high + 1) // 2
            if left[:middle] == right[:middle]:
                low = middle
            else:
                high = middle - 1
        return low

    @staticmethod
    def _column_statistics(strings: np.ndarray):
        """Factorize each column once and compute repetition-based layout scores."""
        _, n_cols = strings.shape
        strong = np.zeros(n_cols, dtype=np.int64)
        light = np.zeros(n_cols, dtype=np.int64)
        codes = []
        lengths = []

        for col in range(n_cols):
            code, unique = pd.factorize(strings[:, col], sort=False)
            code = np.asarray(code, dtype=np.int64)
            unique = [str(value) for value in unique]

            count = np.bincount(code, minlength=len(unique)).astype(np.int64)
            value_lengths = np.asarray(
                [len(value) for value in unique],
                dtype=np.int64,
            )

            # Required length-weighted pair repetition heuristic.
            strong[col] = int(
                np.sum(value_lengths * count * (count - 1))
            )

            # A distinct less-quadratic heuristic approximating repeated insertions.
            light[col] = int(
                np.sum(value_lengths * np.maximum(count - 1, 0))
            )

            codes.append(code)
            lengths.append(value_lengths)

        return strong, light, codes, lengths

    def _serial_score(self, strings: np.ndarray, orders) -> int:
        """Compute exact ideal Trie reuse as sorted serialized-row adjacent LCP sum."""
        n_rows = strings.shape[0]
        if n_rows < 2:
            return 0

        if isinstance(orders, tuple):
            positions = list(orders)
            serial = [
                "".join(strings[row, positions])
                for row in range(n_rows)
            ]
        else:
            serial = [
                "".join(strings[row, list(orders[row])])
                for row in range(n_rows)
            ]

        serial.sort()
        return sum(
            self._lcp(serial[index - 1], serial[index])
            for index in range(1, n_rows)
        )

    @staticmethod
    def _constraint_order(
        base_order: List[int],
        columns: List,
        col_merge: List[List[str]],
        one_way_dep: List[Tuple[str, str]],
    ) -> List[int]:
        """Keep merge groups contiguous and apply dependency precedence when possible."""
        n_cols = len(columns)
        if n_cols < 2 or (not col_merge and not one_way_dep):
            return list(base_order)

        positions_by_name = {}
        for position, name in enumerate(columns):
            positions_by_name.setdefault(name, []).append(position)

        rank = {position: index for index, position in enumerate(base_order)}
        parent = list(range(n_cols))

        def find(item):
            while parent[item] != item:
                parent[item] = parent[parent[item]]
                item = parent[item]
            return item

        def union(left, right):
            left = find(left)
            right = find(right)
            if left != right:
                parent[right] = left

        # Overlapping merge requests form one connected contiguous block.
        for group in col_merge or []:
            members = []
            for name in group:
                members.extend(positions_by_name.get(name, []))
            if len(members) > 1:
                root = members[0]
                for member in members[1:]:
                    union(root, member)

        components = {}
        for position in range(n_cols):
            components.setdefault(find(position), []).append(position)

        blocks = list(components.values())
        for block in blocks:
            block.sort(key=lambda position: rank[position])

        block_of = {}
        block_rank = {}
        for block_id, block in enumerate(blocks):
            block_rank[block_id] = min(rank[position] for position in block)
            for position in block:
                block_of[position] = block_id

        outgoing = [[] for _ in blocks]
        indegree = [0] * len(blocks)
        edges = set()

        for source_name, target_name in one_way_dep or []:
            for source in positions_by_name.get(source_name, []):
                for target in positions_by_name.get(target_name, []):
                    source_block = block_of[source]
                    target_block = block_of[target]
                    if source_block != target_block:
                        edges.add((source_block, target_block))

        for source_block, target_block in edges:
            outgoing[source_block].append(target_block)
            indegree[target_block] += 1

        ready = sorted(
            [block for block in range(len(blocks)) if indegree[block] == 0],
            key=lambda block: block_rank[block],
        )
        result = []

        while ready:
            block = ready.pop(0)
            result.append(block)

            for target in outgoing[block]:
                indegree[target] -= 1
                if indegree[target] == 0:
                    ready.append(target)
                    ready.sort(key=lambda candidate: block_rank[candidate])

        # Keep all fields deterministically if dependency requirements contain a cycle.
        if len(result) != len(blocks):
            seen = set(result)
            result.extend(
                block
                for block in sorted(
                    range(len(blocks)),
                    key=lambda block: block_rank[block],
                )
                if block not in seen
            )

        return [
            position
            for block in result
            for position in blocks[block]
        ]

    @staticmethod
    def _conditional_orders(
        codes,
        lengths,
        default_order: Tuple[int, ...],
        n_rows: int,
        max_depth: int,
    ) -> List[Tuple[int, ...]]:
        """Build a bounded conditional partition tree using factorized value codes."""
        n_cols = len(default_order)
        candidate_cols = tuple(default_order[: min(n_cols, 32)])
        orders = [None] * n_rows

        max_nodes = 384
        nodes = 0
        stack = [
            (
                np.arange(n_rows, dtype=np.int64),
                tuple(),
                candidate_cols,
                0,
            )
        ]

        while stack:
            rows, prefix, remaining, depth = stack.pop()
            nodes += 1

            if (
                len(rows) < 2
                or not remaining
                or depth >= max_depth
                or nodes > max_nodes
            ):
                tail = tuple(
                    col for col in default_order
                    if col not in prefix
                )
                final_order = prefix + tail
                for row in rows:
                    orders[int(row)] = final_order
                continue

            best_col = None
            best_score = 0

            for col in remaining:
                selected_codes = codes[col][rows]
                counts = np.bincount(
                    selected_codes,
                    minlength=len(lengths[col]),
                ).astype(np.int64)

                score = int(
                    np.sum(lengths[col] * counts * (counts - 1))
                )

                if (
                    score > best_score
                    or (
                        score == best_score
                        and best_col is not None
                        and col < best_col
                    )
                ):
                    best_col = col
                    best_score = score

            if best_col is None or best_score <= 0:
                tail = tuple(
                    col for col in default_order
                    if col not in prefix
                )
                final_order = prefix + tail
                for row in rows:
                    orders[int(row)] = final_order
                continue

            selected_codes = codes[best_col][rows]
            sorter = np.argsort(selected_codes, kind="stable")
            sorted_rows = rows[sorter]
            sorted_codes = selected_codes[sorter]
            next_remaining = tuple(
                col for col in remaining
                if col != best_col
            )

            start = 0
            while start < len(sorted_rows):
                end = start + 1
                while (
                    end < len(sorted_rows)
                    and sorted_codes[end] == sorted_codes[start]
                ):
                    end += 1

                stack.append(
                    (
                        sorted_rows[start:end],
                        prefix + (best_col,),
                        next_remaining,
                        depth + 1,
                    )
                )
                start = end

        fallback = tuple(default_order)
        return [
            order if order is not None else fallback
            for order in orders
        ]

    def reorder(
        self,
        df: pd.DataFrame,
        early_stop: int = 0,
        row_stop: int = None,
        col_stop: int = None,
        col_merge: List[List[str]] = [],
        one_way_dep: List[Tuple[str, str]] = [],
        distinct_value_threshold: float = 0.8,
        parallel: bool = True,
    ) -> Tuple[pd.DataFrame, List[List[str]]]:
        """Select among two global and one conditional exact-Trie layout candidates."""
        n_rows, n_cols = df.shape
        columns = list(df.columns)

        if n_rows == 0 or n_cols == 0:
            return df.copy(), [[] for _ in range(n_rows)]

        strings = self._string_matrix(df)
        strong, light, codes, lengths = self._column_statistics(strings)
        positions = list(range(n_cols))

        # Candidate one: required count*(count-1) frequency order.
        frequency_order = sorted(
            positions,
            key=lambda col: (-int(strong[col]), col),
        )

        # Candidate two: less quadratic ordering for repeated useful payloads.
        light_order = sorted(
            positions,
            key=lambda col: (
                -int(light[col]),
                -int(strong[col]),
                col,
            ),
        )

        frequency_order = self._constraint_order(
            frequency_order,
            columns,
            col_merge,
            one_way_dep,
        )
        light_order = self._constraint_order(
            light_order,
            columns,
            col_merge,
            one_way_dep,
        )

        candidates = [tuple(frequency_order)]
        if tuple(light_order) != tuple(frequency_order):
            candidates.append(tuple(light_order))

        # Candidate three provides group-specific suffix orders while remaining bounded.
        if (
            not col_merge
            and not one_way_dep
            and n_rows * n_cols <= 1_250_000
            and n_cols <= 128
        ):
            depth_limit = min(
                8,
                n_cols,
                col_stop if col_stop is not None and col_stop > 0 else 8,
            )
            candidates.append(
                self._conditional_orders(
                    codes,
                    lengths,
                    tuple(frequency_order),
                    n_rows,
                    depth_limit,
                )
            )

        total_chars = sum(len(value) for value in strings.ravel())

        # Exact selection includes partial-field and cross-field prefix reuse.
        if total_chars <= 30_000_000:
            best = max(
                candidates,
                key=lambda candidate: self._serial_score(strings, candidate),
            )
        else:
            best = candidates[0]

        source = df.to_numpy(dtype=object, copy=True)

        if isinstance(best, tuple):
            output = source[:, list(best)]
            row_orders = [best] * n_rows
        else:
            output = np.empty(source.shape, dtype=object)
            for row, order in enumerate(best):
                output[row, :] = source[row, list(order)]
            row_orders = best

        reordered = pd.DataFrame(
            output,
            index=df.index.copy(),
            columns=df.columns.copy(),
            dtype=object,
        )

        column_orderings = [
            [columns[position] for position in order]
            for order in row_orders
        ]

        return reordered, column_orderings
